[
 {
  "number": "1",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "1. A personal reminder digital voice recorder comprising: a) a battery operated audio microchip system for recording, storing and reproducing a single personal audio recording on each of a plurality of channels; b) an individual playback button assigned to each of the plurality of channels; c) an LED corresponding to each of the channels, each LED having a means to turn the LED on when the channel has an active message recorded; and d) a means to turn each LED off when a corresponding channel has a message that is inactive."
 },
 {
  "number": "2",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "2. A digital voice recorder according to claim 1 wherein each LED is on the corresponding playback button."
 },
 {
  "number": "3",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "3. A digital voice recorder according to claim 1 wherein each LED is positioned near the corresponding playback button."
 },
 {
  "number": "4",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "4. A digital voice recorder according to claim 1 wherein there are between 3 and 7 channels."
 },
 {
  "number": "5",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "4"
  ],
  "text": "5. A digital voice recorder according to claim 4 wherein there are from 5 to 7 channels."
 },
 {
  "number": "6",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "6. A digital voice recorder according to claim 1 wherein the total recording time for all channels combined is 15 minutes or less."
 },
 {
  "number": "7",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "7. A digital voice recorder according to claim 1 wherein an LED light automatically comes on any time there is a message on the channel corresponding to the LED."
 },
 {
  "number": "8",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "8. A digital voice recorder according to claim 1 wherein an LED light can be turned off separate from erasing the corresponding message."
 },
 {
  "number": "9",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "9. A digital voice recorder according to claim 1 wherein the LED light corresponding to a channel can be turned on separate from recording a message on the channel."
 },
 {
  "number": "10",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "10. A digital voice recorder according to claim 1 wherein the LED lights corresponding to each channel are a different color."
 },
 {
  "number": "11",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "11. A digital voice recorder according to claim 1 wherein the LED lights corresponding to each channel are the same color."
 },
 {
  "number": "12",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "12. A digital voice recorder according to claim 1 wherein the LED corresponding to each channel is capable of lighting in more than one color."
 },
 {
  "number": "13",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "13. A personal digital recording device comprising a plurality of recording/playback channels wherein there is a playback button operating the playback for each of the channels on the device and there is a light corresponding to each playback button to indicate when the channel has an active message."
 },
 {
  "number": "14",
  "status": "",
